<?php
require __DIR__.'/bootstrap.php';require_auth();if((user()['role_code']??'')!=='main_admin'){http_response_code(403);exit('Only the Main Admin Account can reverse supplier payments.');}require __DIR__.'/partials.php';
$id=(int)($_GET['id']??$_POST['id']??0);$stmt=$db->prepare('SELECT sp.*,s.name supplier,p.purchase_no,p.supplier_invoice,p.balance purchase_balance FROM supplier_payments sp JOIN suppliers s ON s.id=sp.supplier_id LEFT JOIN purchases p ON p.id=sp.purchase_id WHERE sp.id=?');$stmt->execute([$id]);$payment=$stmt->fetch();if(!$payment){http_response_code(404);exit('Payment not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=in_array($_POST['reversal_type']??'',['cheque_returned','payment_reversed','other'],true)?$_POST['reversal_type']:'payment_reversed';$reason=trim($_POST['reason']??'');if($reason===''){flash('danger','Enter the reason for returning or reversing this payment.');redirect('supplier_payment_reverse.php?id='.$id);}$db->beginTransaction();try{$lock=$db->prepare('SELECT * FROM supplier_payments WHERE id=? FOR UPDATE');$lock->execute([$id]);$current=$lock->fetch();if(!$current||$current['status']==='reversed')throw new RuntimeException('This payment has already been reversed.');if(!$current['purchase_id'])throw new RuntimeException('This payment is not connected to a supplier bill.');$purchaseStmt=$db->prepare('SELECT * FROM purchases WHERE id=? FOR UPDATE');$purchaseStmt->execute([$current['purchase_id']]);$purchase=$purchaseStmt->fetch();if(!$purchase)throw new RuntimeException('The related supplier bill was not found.');$amount=(float)$current['amount'];$newPaid=max(0,(float)$purchase['paid_amount']-$amount);$newBalance=min((float)$purchase['total'],(float)$purchase['balance']+$amount);$db->prepare('UPDATE purchases SET paid_amount=?,balance=?,payment_type="credit" WHERE id=?')->execute([$newPaid,$newBalance,$purchase['id']]);$db->prepare('UPDATE suppliers SET outstanding=outstanding+? WHERE id=?')->execute([$amount,$current['supplier_id']]);$db->prepare('UPDATE supplier_payments SET status="reversed",reversal_type=?,reversal_reason=?,reversed_at=NOW(),reversed_by=? WHERE id=?')->execute([$type,$reason,user()['id'],$id]);audit($db,'reverse','supplier_payment',$id,['status'=>'posted','amount'=>$amount],['status'=>'reversed','type'=>$type,'reason'=>$reason,'purchase_balance'=>$newBalance]);$db->commit();flash('success','Payment reversed. The supplier bill and outstanding balance were restored.');redirect('supplier_payments.php');}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('supplier_payment_reverse.php?id='.$id);}}
page_start('Return / Reverse Supplier Payment','purchases.php');?>
<section class="correction-shell"><div class="correction-warning"><b>This creates a financial reversal</b><span>The original payment remains in history. Its amount will be added back to the supplier bill and supplier outstanding balance.</span></div><section class="panel reversal-summary"><span class="eyebrow">Original payment</span><h2><?=e($payment['payment_no'])?></h2><div class="reversal-facts"><p><span>Supplier</span><b><?=e($payment['supplier'])?></b></p><p><span>Purchase</span><b><?=e($payment['purchase_no']??'—')?></b></p><p><span>Paid amount</span><b><?=money($payment['amount'])?></b></p><p><span>Method</span><b><?=e(str_replace('_',' ',$payment['method']))?></b></p><p><span>Reference</span><b><?=e($payment['reference_no']?:'—')?></b></p><p><span>Current status</span><b><?=e($payment['status'])?></b></p></div></section><?php if($payment['status']==='reversed'):?><div class="alert danger">This payment was already reversed: <?=e($payment['reversal_reason'])?></div><?php else:?><form method="post" class="panel reversal-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><label>What happened?<select name="reversal_type"><option value="cheque_returned">Cheque returned / bounced</option><option value="payment_reversed">Payment entered by mistake</option><option value="other">Other return or reversal</option></select></label><label>Reason and details<textarea name="reason" rows="4" required placeholder="Explain why this payment is being reversed"></textarea></label><div class="reversal-warning"><b>This will increase the amount owed by <?=money($payment['amount'])?>.</b></div><button class="btn danger-action wide" data-confirm="Reverse this supplier payment and restore the bill balance?">Confirm Reversal</button><a class="btn secondary wide" href="supplier_payments.php">Cancel</a></form><?php endif;?></section>
<style>.reversal-summary,.reversal-form{padding:24px;margin-bottom:16px}.reversal-summary h2{margin:6px 0 18px}.reversal-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.reversal-facts p{display:flex;flex-direction:column;gap:4px;background:#f7f9f6;padding:12px;border-radius:8px;margin:0}.reversal-facts span{font-size:10px;color:#718078;text-transform:uppercase}.reversal-form{display:grid;gap:14px}.reversal-warning{background:#ffe5e2;color:#a63731;padding:13px;border-radius:8px}.danger-action{background:#b43d36;color:#fff}@media(max-width:650px){.reversal-facts{grid-template-columns:1fr}}</style><?php page_end();
